313→func TestUninstallHooks_PreservesUnknownFields(t *testing.T) {
314→	tempDir := t.TempDir()
315→	t.Chdir(tempDir)
316→
317→	// Install hooks first
318→	ag := &CursorAgent{}
319→	_, err := ag.InstallHooks(false, false)
320→	if err != nil {
321→		t.Fatal(err)
322→	}
323→
324→	// Add unknown fields to the file
325→	hooksPath := filepath.Join(tempDir, ".cursor", HooksFileName)
326→	data, err := os.ReadFile(hooksPath)
327→	if err != nil {
328→		t.Fatal(err)
329→	}
330→
331→	var rawFile map[string]json.RawMessage
332→	if err := json.Unmarshal(data, &rawFile); err != nil {
333→		t.Fatal(err)
334→	}
335→	rawFile["cursorSettings"] = json.RawMessage(`{"theme":"dark"}`)
336→
337→	var rawHooks map[string]json.RawMessage
338→	if err := json.Unmarshal(rawFile["hooks"], &rawHooks); err != nil {
339→		t.Fatal(err)
340→	}
341→	rawHooks["onNotification"] = json.RawMessage(`[{"command":"echo notify"}]`)
342→	hooksJSON, err := json.Marshal(rawHooks)
343→	if err != nil {
344→		t.Fatal(err)
345→	}
346→	rawFile["hooks"] = hooksJSON
347→
348→	updatedData, err := json.MarshalIndent(rawFile, "", "  ")
349→	if err != nil {
350→		t.Fatal(err)
351→	}
352→	if err := os.WriteFile(hooksPath, updatedData, 0o644); err != nil {
353→		t.Fatal(err)
354→	}
355→
356→	// Uninstall hooks
357→	if err := ag.UninstallHooks(); err != nil {
358→		t.Fatalf("UninstallHooks() error = %v", err)
359→	}
360→
361→	// Read and verify unknown fields are preserved
362→	data, err = os.ReadFile(hooksPath)
363→	if err != nil {
364→		t.Fatal(err)
365→	}
366→
367→	if err := json.Unmarshal(data, &rawFile); err != nil {
368→		t.Fatal(err)
369→	}
370→
371→	if _, ok := rawFile["cursorSettings"]; !ok {
372→		t.Error("unknown top-level field 'cursorSettings' was dropped after uninstall")
373→	}
374→
375→	if err := json.Unmarshal(rawFile["hooks"], &rawHooks); err != nil {
376→		t.Fatal(err)
377→	}
378→
379→	if _, ok := rawHooks["onNotification"]; !ok {
380→		t.Error("unknown hook type 'onNotification' was dropped after uninstall")
381→	}
382→
383→	// Verify Entire hooks were actually removed
384→	if ag.AreHooksInstalled() {
385→		t.Error("Entire hooks should be removed after uninstall")
386→	}
387→}
