391→func readHooksFile(t *testing.T, tempDir string) CursorHooksFile {
392→	t.Helper()
393→	hooksPath := filepath.Join(tempDir, ".cursor", HooksFileName)
394→	data, err := os.ReadFile(hooksPath)
395→	if err != nil {
396→		t.Fatalf("failed to read "+HooksFileName+": %v", err)
397→	}
398→
399→	var hooksFile CursorHooksFile
400→	if err := json.Unmarshal(data, &hooksFile); err != nil {
401→		t.Fatalf("failed to parse "+HooksFileName+": %v", err)
402→	}
403→	return hooksFile
404→}
405→
406→func writeHooksFile(t *testing.T, tempDir string, hooksFile CursorHooksFile) {
407→	t.Helper()
408→	cursorDir := filepath.Join(tempDir, ".cursor")
409→	if err := os.MkdirAll(cursorDir, 0o755); err != nil {
410→		t.Fatalf("failed to create .cursor dir: %v", err)
411→	}
412→	data, err := json.MarshalIndent(hooksFile, "", "  ")
413→	if err != nil {
414→		t.Fatalf("failed to marshal "+HooksFileName+": %v", err)
415→	}
416→	hooksPath := filepath.Join(cursorDir, HooksFileName)
417→	if err := os.WriteFile(hooksPath, data, 0o644); err != nil {
418→		t.Fatalf("failed to write "+HooksFileName+": %v", err)
419→	}
420→}
421→
422→func assertEntryCommand(t *testing.T, entries []CursorHookEntry, command string) {
423→	t.Helper()
424→	for _, entry := range entries {
425→		if entry.Command == command {
426→			return
427→		}
428→	}
429→	t.Errorf("hook with command %q not found", command)
430→}
431→
432→func assertEntryWithMatcher(t *testing.T, entries []CursorHookEntry, matcher, command string) {
433→	t.Helper()
434→	for _, entry := range entries {
435→		if entry.Matcher == matcher && entry.Command == command {
436→			return
437→		}
438→	}
439→	t.Errorf("hook with matcher=%q command=%q not found", matcher, command)
440→}
