202→// UninstallHooks removes Entire hooks from Cursor HooksFileName.
203→// Unknown top-level fields and hook types are preserved on round-trip.
204→func (c *CursorAgent) UninstallHooks() error {
205→	repoRoot, err := paths.RepoRoot()
206→	if err != nil {
207→		repoRoot = "."
208→	}
209→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
210→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
211→	if err != nil {
212→		return nil //nolint:nilerr // No hooks file means nothing to uninstall
213→	}
214→
215→	var rawFile map[string]json.RawMessage
216→	if err := json.Unmarshal(data, &rawFile); err != nil {
217→		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
218→	}
219→
220→	var rawHooks map[string]json.RawMessage
221→	if hooksRaw, ok := rawFile["hooks"]; ok {
222→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
223→			return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
224→		}
225→	}
226→	if rawHooks == nil {
227→		rawHooks = make(map[string]json.RawMessage)
228→	}
229→
230→	// Parse only the hook types we manage
231→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
232→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
233→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
234→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
235→	parseCursorHookType(rawHooks, "stop", &stop)
236→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
237→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
238→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
239→
240→	// Remove Entire hooks from all hook types
241→	sessionStart = removeEntireHooks(sessionStart)
242→	sessionEnd = removeEntireHooks(sessionEnd)
243→	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
244→	stop = removeEntireHooks(stop)
245→	preCompact = removeEntireHooks(preCompact)
246→	subagentStart = removeEntireHooks(subagentStart)
247→	subagentStop = removeEntireHooks(subagentStop)
248→
249→	// Marshal modified hook types back into rawHooks
250→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
251→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
252→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
253→	marshalCursorHookType(rawHooks, "stop", stop)
254→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
255→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
256→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
257→
258→	// Marshal hooks back (preserving unknown hook types)
259→	if len(rawHooks) > 0 {
260→		hooksJSON, err := json.Marshal(rawHooks)
261→		if err != nil {
262→			return fmt.Errorf("failed to marshal hooks: %w", err)
263→		}
264→		rawFile["hooks"] = hooksJSON
265→	} else {
266→		delete(rawFile, "hooks")
267→	}
268→
269→	// Write back
270→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
271→	if err != nil {
272→		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
273→	}
274→
275→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
276→		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
277→	}
278→	return nil
279→}
