func TestCalculateTokenUsage_ClaudeCodeBasic(t *testing.T) {
	t.Parallel()

	// A minimal Claude Code JSONL transcript with token usage
	lines := []string{
		`{"type":"human","message":{"content":"hello"}}`,
		`{"type":"assistant","message":{"content":"hi"},"usage":{"input_tokens":10,"output_tokens":5}}`,
	}
	data := []byte(strings.Join(lines, "\n") + "\n")

	result := calculateTokenUsage(agent.AgentTypeClaudeCode, data, 0)
	if result == nil {
		t.Fatal("calculateTokenUsage(ClaudeCode) = nil, want non-nil")
	}
	if result.OutputTokens == 0 {
		t.Error("expected non-zero output tokens for Claude Code transcript with usage data")
	}
}

func TestCalculateTokenUsage_ClaudeCodeWithOffset(t *testing.T) {
	t.Parallel()

	// 4-line transcript; start at offset 2 to only count the second pair
	lines := []string{
		`{"type":"human","message":{"content":"first"}}`,
		`{"type":"assistant","message":{"content":"resp1"},"usage":{"input_tokens":10,"output_tokens":5}}`,
		`{"type":"human","message":{"content":"second"}}`,
		`{"type":"assistant","message":{"content":"resp2"},"usage":{"input_tokens":20,"output_tokens":15}}`,
	}
	data := []byte(strings.Join(lines, "\n") + "\n")

	full := calculateTokenUsage(agent.AgentTypeClaudeCode, data, 0)
	sliced := calculateTokenUsage(agent.AgentTypeClaudeCode, data, 2)

	if full == nil || sliced == nil {
		t.Fatal("expected non-nil results")
	}
	if sliced.OutputTokens >= full.OutputTokens {
		t.Errorf("sliced output tokens (%d) should be less than full (%d)", sliced.OutputTokens, full.OutputTokens)
	}
}

